45:                           JavaTypeBaseInvalidationMode BaseMode) {
46:   JavaTypeCacheInvalidationInfo Info;
47:   const size_t OldBase = BaseTypes.size();
48:   const size_t OldFacts = PathFacts.size();
49:   const size_t OldFinal = FinalTypes.size();
50:   if (OldBase + OldFacts + OldFinal == 0)
51:     return Info;
52: 
53:   // Traverse the old use graph, rather than adding reverse dependency edges
54:   // to every query. This includes non-key values such as a guard condition.
55:   // Bound invalidation work and retain clear() as the conservative fallback.
56:   constexpr unsigned MaxInvalidationValues = 4096;
57:   constexpr unsigned MaxInvalidationUses = 4 * MaxInvalidationValues;
58:   unsigned UsesVisited = 0;
59:   SmallPtrSet<Value *, 32> Affected;
60:   SmallVector<Value *, 32> Worklist(Changed.begin(), Changed.end());
61:   bool DropContext = CFGChanged;
62:   while (!Worklist.empty()) {
63:     Value *V = Worklist.pop_back_val();
64:     if (!V || !Affected.insert(V).second)
65:       continue;
66:     ++Info.ValuesVisited;
67:     if (Info.ValuesVisited > MaxInvalidationValues ||
68:         (!isa<Instruction>(V) && !isa<Argument>(V))) {
69:       Info.FullClear = true;
70:       break;
71:     }
72:     if (auto *I = dyn_cast<Instruction>(V)) {
73:       // Calls include assumptions and changes to nullability attributes.
74:       // LVI also infers non-null facts from dereferences (loads/stores etc.),
75:       // which need not be SSA users of the value whose facts are cached.
76:       // Terminators can change the CFG and edge predicates used by LVI.
77:       DropContext |=
78:           I->isTerminator() || isa<CallBase>(I) || I->mayReadOrWriteMemory();
79:     }
80:     // TODO: (perf)这块的复杂度可以优化么
81:     for (User *U : V->users()) {
82:       if (++UsesVisited > MaxInvalidationUses) {
83:         Info.FullClear = true;
84:         break;
85:       }
86:       // TODO: (perf) 如果Affected中已经包含U，就不需要再次处理了
87:       Worklist.push_back(U);
88:     }
89:     if (Info.FullClear)
90:       break;
91:   }
92:   Info.UsesVisited = UsesVisited;
93: 
94:   auto EraseMatching = [](auto &Map, auto Predicate) {
95:     for (auto It = Map.begin(), End = Map.end(); It != End;) {
96:       auto Current = It++;
97:       if (Predicate(*Current))
98:         Map.erase(Current);
99:     }
100:   };
101:   if (Info.FullClear) {
102:     Info.BaseSlotsScanned = OldBase;
103:     Info.PathFactsSlotsScanned = OldFacts;
104:     Info.FinalTypesSlotsScanned = OldFinal;
105:     clear();
106:   } else {
107:     if (!CFGChanged &&
108:         BaseMode == JavaTypeBaseInvalidationMode::SelectiveKeys) {
109:       // S1: the affected key set is usually much smaller than BaseTypes.
110:       for (Value *V : Affected)
111:         BaseTypes.erase(V);
112:     } else {
113:       // CFG edits must also discard derived entries that are not in the SSA
114:       // use closure. Keep the scan as the S0/A-B baseline and for this case.
115:       EraseMatching(BaseTypes, [&](const auto &Entry) {
116:         ++Info.BaseSlotsScanned;
117:         if (Affected.contains(Entry.first))
118:           return true;
119:         // PHI membership can change without a changed SSA operand being a
120:         // user of the rewritten terminator. Retain only direct, context-free
121:         // leaf computations across a structural CFG edit.
122:         return CFGChanged &&
123:                !isa<Argument, CallBase, LoadInst, Constant>(Entry.first);
124:       });
125:     }
126:     if (DropContext) {
127:       Info.PathFactsSlotsScanned = OldFacts;
128:       Info.FinalTypesSlotsScanned = OldFinal;
129:       PathFacts.clear();
130:       FinalTypes.clear();
131:     } else {
132:       EraseMatching(PathFacts, [&](const auto &Entry) {
133:         ++Info.PathFactsSlotsScanned;
134:         return Affected.contains(Entry.first.first);
135:       });
136:       EraseMatching(FinalTypes, [&](const auto &Entry) {
137:         ++Info.FinalTypesSlotsScanned;
138:         return Affected.contains(Entry.first.first);
139:       });
140:     }
141:   }
142:   Info.BaseRemoved = OldBase - BaseTypes.size();
143:   Info.FactsRemoved = OldFacts - PathFacts.size();
144:   Info.FinalRemoved = OldFinal - FinalTypes.size();
145:   return Info;
146: }
